import { stdout } from std.io;
class User {
    name: String;
    construct(name: String) { this.name = name; }
    label(): String { return this.name; }
    hello(): String { return "hi " + this.label(); }
}
class Admin extends User {
    construct(name: String) { super(name); }
    #override
    label(): String { return "Admin: " + super.label(); }
}
class Root extends Admin {
    construct() { super("root"); }
    #override
    label(): String { return "Root/" + super.label(); }
}
fn main(): Void {
    inmut u: User = Admin("Cris");
    stdout.println(u.label());
    stdout.println(u.hello());
    inmut r: User = Root();
    stdout.println(r.hello());
}
